```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// The causality begins with controlled dependencies
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

const renderCheckout = (props = {}) => {
  return render(
    <CartContext.Provider value={mockCart}>
      <PaymentContext.Provider value={mockPayment}>
        <Checkout {...props} />
      </PaymentContext.Provider>
    </CartContext.Provider>
  );
};

describe('Checkout - The Causality of Commerce', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - The Predetermined Flow', () => {
    it('completes full checkout when all causes align', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      renderCheckout({ onComplete });

      // Shipping - cause leads to effect
      await user.type(screen.getByLabelText(/street address/i), '123 Matrix Lane');
      await user.type(screen.getByLabelText(/city/i), 'Zion');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment - the transaction of power
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Neo Anderson');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and submit
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Validation - Consequences of Incomplete Data', () => {
    it('displays error when street address is empty', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects invalid ZIP format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'INVALID');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Edge Cases - When Causality Breaks', () => {
    it('shows empty cart message when items array is empty', () => {
      mockCart.items = [];
      renderCheckout();

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure with grace', async () => {
      mockPayment.processPayment.mockRejectedValue(new Error('Card declined'));
      const user = userEvent.setup();
      // ... navigate to review step

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
    });
  });

  describe('Accessibility - No One Left Behind', () => {
    it('has no accessibility violations', async () => {
      const { container } = renderCheckout();
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
